@spec arrange_page_spec  src=tests/specs/arrange_page_spec.lua  loc=1239  cases=52
@exercises commandManager (h.cmgr), configManager (h.cm), arrangeManager (am)
@surface   cmgr:registerAll, cm:set, cmgr:push, am:tracksTakes, cmgr:invoke, cmgr:installManifest, cmgr:scope, cm:get, am:resizeTake, am:trimHead, am:trackSlots
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.SetMediaItemSelected, reaper:setCursor

# Intent
  Pin-tests for arrangePage's Page interface and arrange-scope edit commands.
  Cursor mechanics, off-screen no-op, and selection-precedence: arrange_view_spec.

# Helpers
  @fn newArrangePage(cm, ds, cmgr, chrome, gui, help)  @ 46-55
  @fn twoSelected(h)  @ 59-78
      -- Two instances of slot 0, one row each at QN 0 and 1, with rows 0..1 banded.
      -- The siblings at QN 10 and 20 are what slots 0 and 1 clone from.

# Cases
  @case 'bind / unbind are no-ops — arrange page never re-keys cm'  [harness]  @ 82-92
  @case 'the arrange facade enumerates the takes over a span of columns and QN'  [harness]  @ 98-127
  @case 'the arrange facade answers the placement a QN falls in on a track'  [harness]  @ 131-147
  @case 'focusState before any render returns both bits false'  [harness]  @ 151-158
  @case 'arrange-scope is registered at module load (cursorRight invokable)'  [harness]  @ 162-169
  @case 'the manifest declares every command the arrange page registers'  [harness]  @ 176-193
  @case 'every group the arrange page places is one some scope declares'  [harness]  @ 199-214
  @case 'every bound command on the arrange page has a place on the cheat-sheet'  [harness]  @ 221-244
  @case 'arrange-scope place commands are registered (drop0/dropA/dropZ invokable)'  [harness]  @ 248-259
  @case 'a place-command drop advances the cursor by cm.arrangeAdvanceBy rows'  [harness]  @ 263-286
  @case 'arrangeAdvanceBy0..9 set cm.arrangeAdvanceBy at project tier'  [harness]  @ 290-301
  @case 'chained Super-D walks down — each clone becomes the selection for the next'  [harness]  @ 305-324
  @case 'a place-command drop inherits the length of an existing instance'  [harness]  @ 328-350
  @case 'arrangeNudgeForward moves the cursor take by one row'  [harness]  @ 354-368
  @case 'arrangeNudgeForward moves a take taller than one row'  [harness]  @ 372-387
  @case 'arrangeEdgeDown lengthens the cursor take by one row'  [harness]  @ 391-409
  @case 'growing a trimmed take moves its end, leaving the head where it was'  [harness]  @ 413-435
  @case 'arrangeEdgeDown silently no-ops at the take-source length cap'  [harness]  @ 439-454
  @case 'arrangeEdgeUp reduces the cursor take by one row'  [harness]  @ 458-474
  @case 'arrangeDeleteTake removes the cursor take'  [harness]  @ 478-492
  @case 'deleteSlot forever-deletes the cursor take\'s slot behind a confirm'  [harness]  @ 498-522
  @case 'deleteSlot no-ops with the cursor off every take'  [harness]  @ 526-542
  @case 'arrangeNudgeForward is a no-op when the next row is occupied'  [harness]  @ 546-562
  @case 'arrangeNudgeBack is a no-op when the take is already at row 0'  [harness]  @ 566-580
  @case 'arrangeEdgeDown against a flush neighbour stores intent; rendered is gap-capped'  [harness]  @ 584-603
  @case 'arrangeNudgeForward steps past a neighbour without a start-collision'  [harness]  @ 607-627
  @case 'arrangeNudgeForward truncates the displaced take when stepping past'  [harness]  @ 631-653
  @case 'arrangeDive switches to the tracker for the cursor MIDI take'  [harness]  @ 657-672
  @case 'createSlot dives the tracker onto the freshly-minted take'  [harness]  @ 676-691
  @case 'arrangeDive over an audio take still switches and restores (no take pinned)'  [harness]  @ 695-709
  @case 'arrangeDive over empty space switches and restores'  [harness]  @ 713-725
  @case 'the dive carries the caret QN, and carries none over empty space'  [harness]  @ 731-750
  @case 'kb edit acts on the cursor take when nothing is selected'  [harness]  @ 754-772
  @case 'kb delete no-ops when the cursor sits off every take'  [harness]  @ 776-794
  @case 'kb nudge no-ops when cursor sits on empty space'  [harness]  @ 798-815
  @case 'an edit command is a no-op when the cursor is over empty space'  [harness]  @ 819-834
  @case 'a second delete finds an empty cell under the cursor — no-op'  [harness]  @ 838-856
  @case 'seedCursorFromReaper lands the cursor on the selected take'  [harness]  @ 860-877
  @case 'seedCursorFromReaper falls back to the edit-cursor row'  [harness]  @ 881-895
  @case 'arrangeTakeProperties routes the focused MIDI take through the tracker facade'  [harness]  @ 904-917
  @case 'arrangeTakeProperties is a no-op on an audio take'  [harness]  @ 921-934
  @case 'arrangeDuplicateBelow drops a pooled clone at the focused take\'s append point'  [harness]  @ 938-954
  @case 'arrangeDuplicateBelow is silent for want of room and on audio takes'  [harness]  @ 958-976
  @case 'arrangeNextVariant past the last of the family swaps the target for a fresh variant'  [harness]  @ 980-1011
  @case 'arrangeDuplicateBelow then arrangeNextVariant forks the copy onto a fresh slot'  [harness]  @ 1017-1041
  @case 'replace mode: a drop swaps the take under the cursor, keeping its start'  [harness]  @ 1047-1074
  @case 'a replace with a selection held replaces every selected take'  [harness]  @ 1078-1095
  @case 'the replacements become the selection'  [harness]  @ 1099-1111
  @case 'a shorter replacement pulls the cursor back inside it'  [harness]  @ 1115-1143
  @case 'replace mode disarms on the drop it reinterprets — the next drop places'  [harness]  @ 1147-1175
  @case 'a cursor move disarms replace mode'  [harness]  @ 1179-1205
  @case 'a second arrangeReplaceMode disarms — the mode is a toggle'  [harness]  @ 1209-1236

